import static org.assertj.core.api.Assertions.assertThat;

/**
 * 多语种段落发布 API 主流程与失败分支测试。
 */
class TranslationApiTest extends AbstractIntegrationTest {

    @Test
    @DisplayName("建文档：201，初始草稿版本 1、发布版本 0，语言码归一为小写")
